package main

import (
	"bufio"
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"net/url"
	"os"
	"os/exec"
	"sort"
	"strings"
)

func isTTY(file *os.File) bool {
	stat, _ := file.Stat()
	return (stat.Mode() & os.ModeCharDevice) != 0
}

func main() {
	var curlieOptions []string
	var curlOptions []string
	var posArgs []string

	for _, arg := range os.Args[1:] {
		if arg == "--pretty" || arg == "--curl" {
			curlieOptions = append(curlieOptions, arg)
		} else if strings.HasPrefix(arg, "-") && arg != "--" {
			curlOptions = append(curlOptions, arg)
		} else if arg == "--" {
			// Ignore --
		} else {
			posArgs = append(posArgs, arg)
		}
	}

	pretty := false
	showCurl := false
	for _, opt := range curlieOptions {
		if opt == "--pretty" {
			pretty = true
		} else if opt == "--curl" {
			showCurl = true
		}
	}
	if !pretty && isTTY(os.Stdout) {
		pretty = true
	}

	var method, rawURL string
	var items []string

	methods := map[string]bool{
		"GET": true, "POST": true, "PUT": true, "DELETE": true,
		"PATCH": true, "HEAD": true, "OPTIONS": true, "TRACE": true,
	}

	if len(posArgs) >= 2 && methods[strings.ToUpper(posArgs[0])] {
		method = strings.ToUpper(posArgs[0])
		rawURL = posArgs[1]
		items = posArgs[2:]
	} else if len(posArgs) >= 1 {
		rawURL = posArgs[0]
		items = posArgs[1:]
	} else {
		// No URL, just pass --help to curl
		cmd := exec.Command("curl", "--help")
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	// URL parsing for display and curl
	displayURL := rawURL
	if !strings.Contains(displayURL, "://") {
		displayURL = "http://" + displayURL
	}
	fmt.Fprintln(os.Stderr, displayURL)

	curlURL := rawURL
	if strings.HasPrefix(curlURL, ":") {
		curlURL = "localhost" + curlURL
	}

	var headers []string
	data := make(map[string]interface{})
	hasData := false
	queryParams := url.Values{}

	for _, item := range items {
		if strings.Contains(item, "==") {
			parts := strings.SplitN(item, "==", 2)
			queryParams.Add(parts[0], parts[1])
		} else if strings.Contains(item, ":=") {
			parts := strings.SplitN(item, ":=", 2)
			var val interface{}
			if err := json.Unmarshal([]byte(parts[1]), &val); err != nil {
				val = nil
			}
			data[parts[0]] = val
			hasData = true
		} else if strings.Contains(item, "=") {
			parts := strings.SplitN(item, "=", 2)
			data[parts[0]] = parts[1]
			hasData = true
		} else if strings.Contains(item, ":") {
			headers = append(headers, item)
		}
	}

	if len(queryParams) > 0 {
		if strings.Contains(curlURL, "?") {
			curlURL += "&" + queryParams.Encode()
		} else {
			curlURL += "?" + queryParams.Encode()
		}
	}

	var finalCurlArgs []string
	finalCurlArgs = append(finalCurlArgs, curlOptions...)
	if method != "" {
		finalCurlArgs = append(finalCurlArgs, "-X", method)
	}

	for _, h := range headers {
		finalCurlArgs = append(finalCurlArgs, "-H", h)
	}

	if hasData {
		var keys []string
		for k := range data {
			keys = append(keys, k)
		}
		sort.Strings(keys)
		sortedData := make(map[string]interface{}) // Not actually used for JSON marshaling order
		// Go's json.Marshal sorts map keys by default!
		jsonBytes, _ := json.Marshal(data)
		finalCurlArgs = append(finalCurlArgs, "-d", string(jsonBytes))
	}

	finalCurlArgs = append(finalCurlArgs, curlURL)
	finalCurlArgs = append(finalCurlArgs, "-s", "-S")

	if pretty {
		finalCurlArgs = append(finalCurlArgs, "-v")
	}

	if !hasData && !isTTY(os.Stdin) {
		finalCurlArgs = append(finalCurlArgs, "-d@-")
	}

	// Headers
	if hasData || (!hasData && !isTTY(os.Stdin)) {
		finalCurlArgs = append(finalCurlArgs, "-H", "Content-Type: application/json")
	}
	finalCurlArgs = append(finalCurlArgs, "-H", "Accept: application/json, */*")

	if showCurl {
		fmt.Printf("curl %s\n", strings.Join(quoteArgs(finalCurlArgs), " "))
		return
	}

	runCurl(finalCurlArgs, pretty, anyVerbose(curlOptions))
}

func quoteArgs(args []string) []string {
	quoted := make([]string, len(args))
	for i, arg := range args {
		if strings.Contains(arg, " ") || strings.Contains(arg, "\"") || strings.Contains(arg, "{") {
			quoted[i] = fmt.Sprintf("%q", arg)
		} else {
			quoted[i] = arg
		}
	}
	return quoted
}

func anyVerbose(opts []string) bool {
	for _, opt := range opts {
		if opt == "-v" || opt == "--verbose" {
			return true
		}
	}
	return false
}

func runCurl(args []string, pretty bool, verbose bool) {
	cmd := exec.Command("curl", args...)
	cmd.Stdin = os.Stdin

	if !pretty {
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	stdout, _ := cmd.StdoutPipe()
	stderr, _ := cmd.StderrPipe()

	cmd.Start()

	go handleStderr(stderr, verbose)
	handleStdout(stdout)

	cmd.Wait()
}

func handleStderr(r io.Reader, verbose bool) {
	scanner := bufio.NewScanner(r)
	for scanner.Scan() {
		line := scanner.Text()
		if strings.HasPrefix(line, "* ") {
			if verbose {
				fmt.Fprintf(os.Stderr, "\033[90m%s\033[0m\n", line)
			}
		} else if strings.HasPrefix(line, "> ") {
			if verbose {
				printColoredHeader(line[2:], os.Stderr, true)
			}
		} else if strings.HasPrefix(line, "< ") {
			printColoredHeader(line[2:], os.Stderr, false)
		} else {
			// Other stderr output from curl?
			fmt.Fprintln(os.Stderr, line)
		}
	}
}

func printColoredHeader(line string, out io.Writer, isRequest bool) {
	line = strings.TrimRight(line, "\r")
	if strings.Contains(line, "HTTP/") {
		// Request line or status line
		if isRequest {
			// Method Path Protocol/Version
			parts := strings.SplitN(line, " ", 3)
			if len(parts) == 3 {
				fmt.Fprintf(out, "\033[34m%s\033[37m %s \033[34m%s\033[37m/\033[36m%s\033[0m\n", 
					parts[0], parts[1], strings.Split(parts[2], "/")[0], strings.Split(parts[2], "/")[1])
			} else {
				fmt.Fprintf(out, "%s\n", line)
			}
		} else {
			// Protocol/Version Status StatusText
			parts := strings.SplitN(line, " ", 3)
			if len(parts) >= 2 {
				protoParts := strings.Split(parts[0], "/")
				fmt.Fprintf(out, "\033[34m%s\033[37m/\033[36m%s %s\033[33m%s\033[0m\n",
					protoParts[0], protoParts[1], parts[1], func() string {
						if len(parts) == 3 { return " " + parts[2] }
						return ""
					}())
			} else {
				fmt.Fprintf(out, "%s\n", line)
			}
		}
	} else if strings.Contains(line, ":") {
		parts := strings.SplitN(line, ":", 2)
		fmt.Fprintf(out, "\033[37m%s:\033[36m%s\033[0m\n", parts[0], parts[1])
	} else if line == "" {
		fmt.Fprintln(out, "")
	} else {
		fmt.Fprintln(out, line)
	}
}

func handleStdout(r io.Reader) {
	// Try to read the whole thing and see if it's JSON
	// For streaming on the fly, it's more complex, but let's try a simple version first.
	body, _ := io.ReadAll(r)
	if len(body) == 0 {
		return
	}

	var jsonVal interface{}
	if err := json.Unmarshal(body, &jsonVal); err == nil {
		prettyJSON, _ := json.MarshalIndent(jsonVal, "", "    ")
		colorPrintJSON(string(prettyJSON))
	} else {
		os.Stdout.Write(body)
	}
}

func colorPrintJSON(s string) {
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		// Naive coloring
		var coloredLine strings.Builder
		i := 0
		for i < len(line) {
			if line[i] == '"' {
				end := strings.Index(line[i+1:], "\"")
				if end != -1 {
					end += i + 1
					isKey := false
					// Check if it's a key (followed by :)
					for j := end + 1; j < len(line); j++ {
						if line[j] == ':' {
							isKey = true
							break
						}
						if !unicode.IsSpace(rune(line[j])) {
							break
						}
					}
					if isKey {
						coloredLine.WriteString("\033[34m")
					} else {
						coloredLine.WriteString("\033[36m")
					}
					coloredLine.WriteString(line[i : end+1])
					coloredLine.WriteString("\033[37m")
					i = end + 1
				} else {
					coloredLine.WriteByte(line[i])
					i++
				}
			} else if unicode.IsDigit(rune(line[i])) || (line[i] == '-' && i+1 < len(line) && unicode.IsDigit(rune(line[i+1]))) {
				coloredLine.WriteString("\033[36m")
				for i < len(line) && (unicode.IsDigit(rune(line[i])) || line[i] == '.' || line[i] == 'e' || line[i] == 'E' || line[i] == '-') {
					coloredLine.WriteByte(line[i])
					i++
				}
				coloredLine.WriteString("\033[37m")
			} else if strings.HasPrefix(line[i:], "true") {
				coloredLine.WriteString("\033[35mtrue\033[37m")
				i += 4
			} else if strings.HasPrefix(line[i:], "false") {
				coloredLine.WriteString("\033[35mfalse\033[37m")
				i += 5
			} else if strings.HasPrefix(line[i:], "null") {
				coloredLine.WriteString("\033[35mnull\033[37m")
				i += 4
			} else {
				if !unicode.IsSpace(rune(line[i])) {
					coloredLine.WriteString("\033[37m")
					coloredLine.WriteByte(line[i])
					// No reset yet
				} else {
					coloredLine.WriteByte(line[i])
				}
				i++
			}
		}
		fmt.Println(coloredLine.String())
	}
	fmt.Print("\033[0m")
}
EOF
"}

