		cmd := exec.Command("curl", "--help")
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		cmd.Run()
		return
	}

	// URL parsing for display and curl
	displayURL := rawURL
	if !strings.Contains(displayURL, "://") {
		displayURL = "http://" + displayURL
	}
	fmt.Fprintln(os.Stderr, displayURL)

	curlURL := rawURL
	if strings.HasPrefix(curlURL, ":") {
		curlURL = "localhost" + curlURL
	}

	var headers []string
	data := make(map[string]interface{})
	hasData := false
	queryParams := url.Values{}

	for _, item := range items {
		if strings.Contains(item, "==") {
			parts := strings.SplitN(item, "==", 2)
			queryParams.Add(parts[0], parts[1])
		} else if strings.Contains(item, ":=") {
			parts := strings.SplitN(item, ":=", 2)
			var val interface{}
			if err := json.Unmarshal([]byte(parts[1]), &val); err != nil {
				val = nil
			}
			data[parts[0]] = val
			hasData = true
		} else if strings.Contains(item, "=") {
			parts := strings.SplitN(item, "=", 2)
			data[parts[0]] = parts[1]
			hasData = true
		} else if strings.Contains(item, ":") {
			headers = append(headers, item)
		}
	}

	if len(queryParams) > 0 {
		if strings.Contains(curlURL, "?") {
			curlURL += "&" + queryParams.Encode()
		} else {
			curlURL += "?" + queryParams.Encode()
		}
	}

