			fmt.Fprintf(out, "%s\n", line)
		}
	} else if strings.HasPrefix(line, "HTTP/") {
		parts := strings.SplitN(line, " ", 3)
		if len(parts) >= 2 {
			protoParts := strings.SplitN(parts[0], "/", 2)
			if len(protoParts) == 2 {
				status := parts[1]
				text := ""
				if len(parts) == 3 {
					text = " " + parts[2]
				}
				fmt.Fprintf(out, "\033[34m%s\033[37m/\033[36m%s %s\033[33m%s\033[0m\n",
					protoParts[0], protoParts[1], status, text)
			} else {
				fmt.Fprintf(out, "%s\n", line)
			}
		} else {
			fmt.Fprintf(out, "%s\n", line)
		}
	} else if strings.Contains(line, ":") {
		parts := strings.SplitN(line, ":", 2)
		fmt.Fprintf(out, "\033[37m%s:\033[36m%s\033[0m\n", parts[0], parts[1])
	} else {
		fmt.Fprintln(out, line)
	}
}

func handleStdout(r io.Reader) {
	body, _ := io.ReadAll(r)
	if len(body) == 0 {
		return
	}

	var jsonVal interface{}
	if err := json.Unmarshal(body, &jsonVal); err == nil {
		prettyJSON, _ := json.MarshalIndent(jsonVal, "", "    ")
		colorPrintJSON(string(prettyJSON))
	} else {
		os.Stdout.Write(body)
	}
}

func colorPrintJSON(s string) {
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		var coloredLine strings.Builder
		i := 0
		for i < len(line) {
			if line[i] == '"' {
				start := i
				i++
				for i < len(line) && (line[i] != '"' || line[i-1] == '\\') {
					i++
				}
				if i < len(line) {
					i++
					end := i
					isKey := false
					for j := i; j < len(line); j++ {
						if line[j] == ':' {
							isKey = true
							break
						}
						if !unicode.IsSpace(rune(line[j])) {
							break
						}
					}
					if isKey {
						coloredLine.WriteString("\033[34m")
					} else {
						coloredLine.WriteString("\033[36m")
					}
					coloredLine.WriteString(line[start:end])
					i = end
				}
			} else if unicode.IsDigit(rune(line[i])) || (line[i] == '-' && i+1 < len(line) && unicode.IsDigit(rune(line[i+1]))) {
				start := i
				for i < len(line) && (unicode.IsDigit(rune(line[i])) || line[i] == '.' || line[i] == 'e' || line[i] == 'E' || line[i] == '-') {
					i++
				}
				coloredLine.WriteString("\033[36m")
				coloredLine.WriteString(line[start:i])
			} else if strings.HasPrefix(line[i:], "true") {
				coloredLine.WriteString("\033[35mtrue")
				i += 4
			} else if strings.HasPrefix(line[i:], "false") {
				coloredLine.WriteString("\033[35mfalse")
				i += 5
			} else if strings.HasPrefix(line[i:], "null") {
				coloredLine.WriteString("\033[35mnull")
				i += 4
			} else {
				if !unicode.IsSpace(rune(line[i])) {
					coloredLine.WriteString("\033[37m")
					coloredLine.WriteByte(line[i])
				} else {
					coloredLine.WriteByte(line[i])
				}
				i++
			}
		}
		fmt.Printf("%s\033[0m\n", coloredLine.String())
	}
}
